/**
 * Builds the local data-collection artefacts that do NOT need the network.
 *
 *  1. data/generated/harvest-spec.json  - snapshot of the reviewed harvest list
 *  2. data/generated/lab-tests.json      - structured lab test reference dataset
 *  3. data/generated/cbc-synthetic.json  - synthetic CBC + report corpus
 *  4. data/generated/sample-reports/*.txt - synthetic multi-layout report OCR
 *
 * Synthetic data policy
 * ---------------------
 * The CBC and report corpora are 100% synthetic. They are generated by
 * `buildSyntheticReport()` from a seeded PRNG. Every patient name is from a
 * fixed list of clearly fictional placeholders, and every identifier is a
 * synthetic counter. No real patient data is used, copied, or approximated from
 * any real person. This is what lets us test the parser against many report
 * layouts without touching anyone's health information.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { HARVEST_SPECS } from '../src/data/harvest-spec';
import { buildSyntheticCbcDataset, buildSyntheticReportText } from '../src/data/synthetic-reports';

const OUT_DIR = resolve('./data/generated');
const REPORT_DIR = join(OUT_DIR, 'sample-reports');

async function main(): Promise<void> {
  await mkdir(REPORT_DIR, { recursive: true });

  // 1. Harvest spec snapshot (reviewed, version-controlled input to the network stage)
  await writeFile(join(OUT_DIR, 'harvest-spec.json'), JSON.stringify(HARVEST_SPECS, null, 2), 'utf8');
  console.log(`wrote data/generated/harvest-spec.json (${HARVEST_SPECS.length} topics)`);

  // 2. Lab test reference dataset
  const { LAB_TEST_RECORDS, REFERENCE_RANGES } = await import('../src/data/lab-tests');
  await writeFile(
    join(OUT_DIR, 'lab-tests.json'),
    JSON.stringify({ generatedAt: new Date().toISOString(), tests: LAB_TEST_RECORDS, referenceRanges: REFERENCE_RANGES }, null, 2),
    'utf8',
  );
  console.log(`wrote data/generated/lab-tests.json (${LAB_TEST_RECORDS.length} analytes, ${REFERENCE_RANGES.length} reference intervals)`);

  // 3. Synthetic CBC dataset
  const cbc = buildSyntheticCbcDataset(240);
  await writeFile(join(OUT_DIR, 'cbc-synthetic.json'), JSON.stringify(cbc, null, 2), 'utf8');
  console.log(`wrote data/generated/cbc-synthetic.json (${cbc.length} records)`);

  // 4. Multi-layout sample reports
  const layouts = buildSyntheticReportText(cbc.slice(0, 24));
  let n = 0;
  for (const doc of layouts) {
    await writeFile(join(REPORT_DIR, `${doc.id}.txt`), doc.text, 'utf8');
    await writeFile(join(REPORT_DIR, `${doc.id}.meta.json`), JSON.stringify(doc.meta, null, 2), 'utf8');
    n += 1;
  }
  console.log(`wrote data/generated/sample-reports/ (${n} documents across ${new Set(layouts.map((d) => d.meta.layout)).size} layouts)`);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
